using CertDesk.Models; using CertDesk.Common;
namespace CertDesk.Forms;
public partial class EmployeeEditForm:Form { public Employee Employee {get;} TextBox n=new(){Width=260},p=new(){Width=260},d=new(){Width=260},e=new(){Width=260},ph=new(){Width=260},s=new(){Width=260},inn=new(){Width=260}; CheckBox a=new(){Text="Активен",Checked=true}; public EmployeeEditForm(Employee? emp=null){Employee=emp??new Employee(); InitializeComponent(); Build(); if(emp!=null) LoadE();} void Build(){ var y=15; foreach(var item in new[]{("ФИО",n),("Должность",p),("Подразделение",d),("Email",e),("Телефон",ph),("СНИЛС",s),("ИНН",inn)}){ Controls.Add(new Label{Text=item.Item1,Left=20,Top=y+3,Width=120}); item.Item2.Left=150; item.Item2.Top=y; Controls.Add(item.Item2); y+=38;} a.Left=150; a.Top=y; Controls.Add(a); var ok=new Button{Text="Сохранить",Left=150,Top=y+45,Width=120}; var cancel=new Button{Text="Отмена",Left=285,Top=y+45,Width=100,DialogResult=DialogResult.Cancel}; UiTheme.ApplyButtonStyle(ok); Controls.AddRange(new Control[]{ok,cancel}); ok.Click+=Save;} void LoadE(){n.Text=Employee.FullName;p.Text=Employee.Position;d.Text=Employee.Department;e.Text=Employee.Email;ph.Text=Employee.Phone;s.Text=Employee.Snils;inn.Text=Employee.Inn;a.Checked=Employee.IsActive;} void Save(object? _,EventArgs __){ if(string.IsNullOrWhiteSpace(n.Text)||string.IsNullOrWhiteSpace(p.Text)){MessageHelper.Error("ФИО и должность обязательны");return;} if(e.TextLength>0&&!e.Text.Contains('@')){MessageHelper.Error("Некорректный email");return;} Employee.FullName=n.Text.Trim();Employee.Position=p.Text.Trim();Employee.Department=d.Text.Trim();Employee.Email=e.Text.Trim();Employee.Phone=ph.Text.Trim();Employee.Snils=s.Text.Trim();Employee.Inn=inn.Text.Trim();Employee.IsActive=a.Checked; DialogResult=DialogResult.OK;} }
